for(let i=0;i<5;i++){const d=makeDino(false);d.position.set((Math.random()-.5)*220,0,(Math.random()-.5)*220);d.scale.setScalar(.8);d.userData.predator=true;predators.push(d);scene.add(d)}

// Modelo realista CC Attribution (Wormhole Studio)
const loader=new GLTFLoader();
loader.load('/public/models/carnotaurus.glb',gltf=>{
  const template=gltf.scene;
  template.updateMatrixWorld(true);
  const box=new THREE.Box3().setFromObject(template);
  const size=new THREE.Vector3();box.getSize(size);
  const center=new THREE.Vector3();box.getCenter(center);
  template.position.sub(center);

  function equipReal(dino,big=false){
    dino.children.forEach(child=>child.visible=false);
    const wrapper=new THREE.Group();
    const model=template.clone(true);
    const scale=(big?10.5:5.8)/Math.max(size.x,size.y,size.z);
    model.scale.setScalar(scale);
    model.rotation.y=Math.PI/2;
    model.position.y=.05;
    model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;o.frustumCulled=false}});
    wrapper.add(model);dino.add(wrapper);
    dino.userData.real=true;
    if(gltf.animations.length){
      const mixer=new THREE.AnimationMixer(model);
      mixer.clipAction(gltf.animations[0]).play();
      dino.userData.mixer=mixer;
    }
  }
  equipReal(player,true);
  prey.forEach(p=>equipReal(p,false));
  predators.forEach(d=>equipReal(d,false));
},undefined,error=>console.error('Erro ao carregar Carnotaurus:',error));

