const template=gltf.scene;
// Um dente solto no GLB tem vértices deslocados a mais de 100 unidades;
// removê-lo evita que ele distorça a escala e o enquadramento do animal.
const outliers=[];
template.traverse(o=>{
  if(!o.isMesh)return;
  o.geometry.computeBoundingBox();
  const dimensions=new THREE.Vector3();o.geometry.boundingBox.getSize(dimensions);
  if(Math.max(dimensions.x,dimensions.y,dimensions.z)>50)outliers.push(o);
});
outliers.forEach(o=>o.parent?.remove(o));
template.updateMatrixWorld(true);
const box=new THREE.Box3().setFromObject(template);
const size=new THREE.Vector3();box.getSize(size);
const center=new THREE.Vector3();box.getCenter(center);
// Centraliza o corpo horizontalmente e apoia os pés no chão.
template.position.set(-center.x,-box.min.y,-center.z);

